#define stdin 0
#define stdout 1
#define stderr 2
#define standard_input_descriptor 0
#define standard_output_descriptor 1
#define standard_error_descriptor 2

#define SIGTRAP 5
#define SIGKILL 9
#define SIGSTOP 19
#define SIGCHLD 17

#define O_NOCTTY 0400
#define O_NONBLOCK 04000
/*
        arm64 is the one architecture that did not take asm-generic's fcntl.

        0200000 is O_DIRECTORY everywhere else and O_DIRECT there, so asking
        to open a directory asked for unbuffered io on one instead and came
        back EINVAL. Globbing opens a directory to read it, so there was no
        globbing at all on arm64 -- a pattern that matched nothing stayed a
        pattern, quietly.
*/
#if ARM64
#define O_DIRECTORY 040000
#define O_NOFOLLOW 0100000
#else
#define O_DIRECTORY 0200000
#define O_NOFOLLOW 0400000
#endif
#define AT_FDCWD -100
#ifndef AT_SYMLINK_NOFOLLOW
#define AT_SYMLINK_NOFOLLOW 0x100
#endif
#ifndef AT_REMOVEDIR
#define AT_REMOVEDIR 0x200
#endif
#ifndef AT_EACCESS
#define AT_EACCESS AT_REMOVEDIR
#endif
#ifndef AT_SYMLINK_FOLLOW
#define AT_SYMLINK_FOLLOW 0x400
#endif
#ifndef AT_NO_AUTOMOUNT
#define AT_NO_AUTOMOUNT 0x800
#endif
#ifndef AT_EMPTY_PATH
#define AT_EMPTY_PATH 0x1000
#endif
#define O_TRUNC 01000
#define O_CLOEXEC 02000000
#define O_PATH 010000000

#define FILE_READ 00
#define FILE_WRITE (01 | 0100 | 01000)
#define FILE_READ_WRITE 02
#define FILE_EXECUTE 010
#define FILE_APPEND (01 | 0100 | 02000)
#define FILE_CREATE 0100
#define FILE_EXCLUSIVE 0200
// O_TRUNC. FILE_WRITE already carries it; 0200 was O_EXCL, which
// refused to open any file that already existed.
#define FILE_TRUNCATE 01000

// POSIX spellings of the same bits. FILE_WRITE and FILE_APPEND are
// combinations; fopen still needs the individual O_WRONLY and O_APPEND.
#ifndef O_RDONLY
#define O_RDONLY FILE_READ
#endif
#ifndef O_WRONLY
#define O_WRONLY 01
#endif
#ifndef O_RDWR
#define O_RDWR FILE_READ_WRITE
#endif
#ifndef O_CREAT
#define O_CREAT FILE_CREATE
#endif
#ifndef O_EXCL
#define O_EXCL FILE_EXCLUSIVE
#endif
#ifndef O_APPEND
#define O_APPEND 02000
#endif

/*
        mmap's own numbers, which these were not.

        They had been given the octal values that sit beside them in the open
        flags above -- 0400 and 01000 and so on -- so every mapping was asked
        for with a protection of 384 and flags of 2560, and the kernel refused
        every one: EBADF on x86_64, EINVAL on arm64 and riscv64. file_load
        could not succeed on any machine and its whole success path was
        unreachable.

        The same on all three: asm-generic/mman-common.h, and no architecture
        here overrides it.
*/
#define FILE_PROTECT_NONE 0
#define FILE_PROTECT_READ 1
#define FILE_PROTECT_WRITE 2
#define FILE_PROTECT_EXECUTE 4

#define FILE_MAP_SHARED 1
#define FILE_MAP_PRIVATE 2
#define FILE_MAP_ANONYMOUS 0x20

#define FILE_SEEK_SET 0
#define FILE_SEEK_CUR 1
#define FILE_SEEK_END 2
#ifndef SEEK_SET
#define SEEK_SET FILE_SEEK_SET
#define SEEK_CUR FILE_SEEK_CUR
#define SEEK_END FILE_SEEK_END
#endif

/*
        The syscall table for Linux and Apple platforms.

        example usage without of C:
                syscall(read) // returns syscall_linux_x64_read ( 0 )
*/
#if defined(__linux__) || defined(__unix__)

#if defined(__x86_64__) || defined(_M_X64)
#define syscall(name) syscall_linux_x64_##name
#endif

#if defined(__aarch64__) || defined(_M_ARM64)
#define syscall(name) syscall_linux_arm64_##name
#endif

//
//      riscv64 is the same numbering as arm64, not a table of its own: both
//      are the asm-generic syscall ABI, and every one of the 306 entries below
//      that resolves to a number was checked against the riscv64 toolchain's
//      own asm/unistd.h and agreed.
//
//      There used to be a separate riscv64 table here. It had 113 of the 322
//      entries, so a program calling clone, execve, setsid or wait4 did not
//      compile -- and four of the entries it did have (timer_gettime,
//      timerfd_settime, timerfd_gettime, utimensat) carried the 32-bit time32
//      numbers, 408 and 410 through 412, where rv64 uses 108 and 86 through
//      88. Those would have compiled and called the wrong thing.
//
//      The one place the two genuinely differ is renameat, which riscv never
//      had; see shell_mv, which calls renameat2 for that reason.
//
#if defined(__riscv)
#define syscall(name) syscall_linux_arm64_##name
#endif

#endif

#ifdef MACOS

#if defined(__x86_64__) || defined(_M_X64)
#define syscall(name) syscall_macos_x64_##name
#endif

#if defined(__aarch64__) || defined(_M_ARM64)
#define syscall(name) syscall_macos_arm64_##name | 0x2000000
#endif

#endif

